const crypto = require('crypto');
const accessKey = 'yCrnfHeNp7sKC5h3';
const secretKey = 'Em2sPDj0VaRGvnnY';
const baseUrl = 'https://metersphere.devops.moego.pet';
const projectId = '20a78db9-19aa-11ee-a261-5a66b98c4036';
const workspaceId = '20a7019f-19aa-11ee-a261-5a66b98c4036';

const timestamp = Date.now();
const uuid = crypto.randomUUID();
const comboxKey = `${accessKey}|${uuid}|${timestamp}`;
const k = Buffer.from(secretKey.slice(0, 16), 'utf-8');
const iv = Buffer.from(accessKey.slice(0, 16), 'utf-8');
const cipher = crypto.createCipheriv('aes-128-cbc', k, iv);
let signature = cipher.update(comboxKey, 'utf-8', 'base64');
signature += cipher.final('base64');

const input = $input.first().json;
const caseName = String(input.name ?? '').trim();
if (!caseName) throw new Error('[validation_error] name is required');
if (caseName.length > 255) throw new Error('[validation_error] name must not exceed 255 characters');
if (!input.node_id && !input.node_path) throw new Error('[validation_error] node_id or node_path is required');

const priority = input.priority || 'P2';
if (!['P0', 'P1', 'P2', 'P3'].includes(priority)) {
  throw new Error('[validation_error] priority must be one of P0, P1, P2, P3');
}
const maintainer = input.maintainer || 'jiabowang@moego.pet';


function normalizeArrayField(value, fieldName, fallback) {
  if (value === undefined || value === null || value === '') {
    return JSON.stringify(fallback);
  }

  let parsed = value;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return JSON.stringify(fallback);

    if (trimmed.startsWith('[')) {
      try {
        parsed = JSON.parse(trimmed);
      } catch (error) {
        throw new Error(fieldName + ' must be valid JSON: ' + error.message);
      }
    } else {
      const example = fieldName === 'tags'
        ? '["回归","P0"]'
        : '[{"num":1,"desc":"操作步骤","result":"预期结果"}]';
      throw new Error(fieldName + ' must be a JSON array string, for example: ' + example);
    }
  }

  if (!Array.isArray(parsed)) {
    throw new Error(fieldName + ' must be an array');
  }

  if (fieldName === 'tags') {
    parsed = parsed.map((tag) => String(tag).trim()).filter(Boolean);
  } else if (fieldName === 'steps') {
    parsed = parsed.map((step, index) => {
      if (!step || typeof step !== 'object' || Array.isArray(step)) {
        throw new Error('steps[' + index + '] must be an object');
      }
      return {
        ...step,
        id: step.id || crypto.randomUUID().replace(/-/g, '').slice(0, 8),
        num: Number.isFinite(Number(step.num)) ? Number(step.num) : index + 1,
        desc: String(step.desc ?? ''),
        result: String(step.result ?? ''),
      };
    });
  }

  return JSON.stringify(parsed);
}


function normalizeNodePath(value) {
  const normalized = String(value ?? '').trim().replace(/\/+/g, '/').replace(/\/$/, '');
  if (!normalized) return '';
  return normalized.startsWith('/') ? normalized : '/' + normalized;
}

async function resolveTargetNode(requestedNodeId, requestedNodePath) {
  const response = await helpers.httpRequest({
    method: 'GET',
    url: baseUrl + '/track/case/node/list/' + projectId,
    headers: {
      'Content-Type': 'application/json',
      'ACCEPT': 'application/json',
      'accessKey': accessKey,
      'signature': signature,
      'project': projectId,
      'workspace': workspaceId,
    },
    json: true,
  });

  const data = typeof response === 'string' ? JSON.parse(response) : response;
  if (!data.success) throw new Error('[upstream_error] Unable to read MeterSphere module tree: ' + data.message);

  const modules = [];
  function flatten(nodes, parentPath = '') {
    for (const node of nodes || []) {
      const path = parentPath ? parentPath + '/' + node.name : '/' + node.name;
      const children = Array.isArray(node.children) ? node.children : [];
      modules.push({
        id: node.id,
        name: node.name,
        path,
        parentId: node.parentId || null,
        childCount: children.length,
      });
      flatten(children, path);
    }
  }
  flatten(data.data);

  const normalizedPath = normalizeNodePath(requestedNodePath);
  let target = null;
  if (normalizedPath) {
    const pathMatches = modules.filter((module) => module.path === normalizedPath);
    if (pathMatches.length === 0) {
      throw new Error('[validation_error] node_path was not found: ' + normalizedPath);
    }
    if (pathMatches.length > 1) {
      throw new Error('[validation_error] node_path is ambiguous; pass the exact node_id: ' + normalizedPath);
    }
    target = pathMatches[0];
    if (requestedNodeId && target.id !== requestedNodeId) {
      throw new Error(
        '[validation_error] node_id and node_path do not identify the same module. '
        + 'Path resolves to ' + target.id + ', but received ' + requestedNodeId,
      );
    }
  } else {
    target = modules.find((module) => module.id === requestedNodeId) || null;
    if (!target) {
      throw new Error('[validation_error] node_id was not found in the MeterSphere module tree: ' + requestedNodeId);
    }
  }

  if (target.childCount > 0) {
    throw new Error(
      '[validation_error] target module is not a leaf. Select one of its child modules instead: '
      + target.path + ' (' + target.childCount + ' children)',
    );
  }
  return target;
}

const targetNode = await resolveTargetNode(input.node_id, input.node_path);
const targetNodeId = targetNode.id;
const nodePath = targetNode.path;

const body = {
  name: caseName,
  num: '',
  nodePath,
  maintainer,
  priority,
  type: 'functional',
  method: '',
  prerequisite: input.prerequisite || '',
  testId: '[]',
  nodeId: targetNodeId,
  steps: normalizeArrayField(input.steps, 'steps', [{ id: crypto.randomUUID().slice(0, 8), num: 1, desc: '', result: '' }]),
  stepDesc: '',
  stepResult: '',
  selected: [],
  remark: '',
  tags: normalizeArrayField(input.tags, 'tags', []),
  demandId: '',
  demandName: '',
  status: 'Prepare',
  reviewStatus: 'Prepare',
  stepDescription: input.step_description || '',
  expectedResult: input.expected_result || '',
  stepModel: input.step_model || null,
  customNum: '',
  followPeople: '',
  versionId: '',
  fields: [],
  id: null,
  projectId,
  casePublic: false,
  addFields: [
    {fieldId: '46065143-9d1d-11eb-b418-0242ac120002', value: JSON.stringify(maintainer)},
    {fieldId: '4619cc23-9d1d-11eb-b418-0242ac120002', value: JSON.stringify(priority)},
    {fieldId: '45f2de57-9d1d-11eb-b418-0242ac120002', value: '"Prepare"'},
  ],
  editFields: [],
  requestFields: [
    {id: '46065143-9d1d-11eb-b418-0242ac120002', name: '责任人', customData: null, type: 'member', value: maintainer},
    {id: '4619cc23-9d1d-11eb-b418-0242ac120002', name: '用例等级', customData: null, type: 'select', value: priority},
    {id: '45f2de57-9d1d-11eb-b418-0242ac120002', name: '用例状态', customData: null, type: 'select', value: 'Prepare'},
  ],
};

if (input.dry_run === true) {
  return [{ json: { success: true, dry_run: true, name: caseName, node_id: targetNodeId, node_path: nodePath, is_leaf: true, priority, message: 'Validation passed; no test case was created' } }];
}

const boundary = '------WebKitFormBoundary' + crypto.randomUUID().replace(/-/g, '').slice(0, 16);
const rawBody = '--' + boundary + '\r\nContent-Disposition: form-data; name="request"; filename="blob"\r\nContent-Type: application/json\r\n\r\n' + JSON.stringify(body) + '\r\n--' + boundary + '--\r\n';

const response = await helpers.httpRequest({
  method: 'POST',
  url: `${baseUrl}/track/test/case/add`,
  headers: {
    'Content-Type': `multipart/form-data; boundary=${boundary}`,
    'ACCEPT': 'application/json',
    'accessKey': accessKey,
    'signature': signature,
    'project': projectId,
    'workspace': workspaceId,
  },
  body: rawBody,
  json: false,
});

const data = typeof response === 'string' ? JSON.parse(response) : response;
if (!data.success) throw new Error('[upstream_error] MeterSphere create failed: ' + data.message);
const c = data.data;

const detailResponse = await helpers.httpRequest({
  method: 'GET',
  url: baseUrl + '/track/test/case/get/' + c.id,
  headers: {
    'Content-Type': 'application/json',
    'ACCEPT': 'application/json',
    'accessKey': accessKey,
    'signature': signature,
    'project': projectId,
    'workspace': workspaceId,
  },
  json: true,
});
const detail = typeof detailResponse === 'string' ? JSON.parse(detailResponse) : detailResponse;
if (!detail.success) {
  throw new Error('[postcondition_error] Test case ' + c.id + ' was created, but detail verification failed: ' + detail.message);
}
const created = detail.data;
const actualPath = normalizeNodePath(created.nodePath);
if (created.nodeId !== targetNodeId || actualPath !== nodePath) {
  throw new Error(
    '[postcondition_error] Test case ' + c.id + ' was created in an unexpected module. '
    + 'Expected node_id=' + targetNodeId + ', node_path=' + nodePath
    + '; actual node_id=' + created.nodeId + ', node_path=' + actualPath,
  );
}

return [{ json: {
  id: created.id,
  num: created.num,
  name: created.name,
  project_id: created.projectId,
  node_id: created.nodeId,
  node_path: actualPath,
  priority: created.priority,
  status: created.status,
  maintainer: created.maintainer,
  verified: true,
  create_time: created.createTime ? new Date(created.createTime).toISOString() : null,
  message: 'Test case created and module ownership verified',
} }];
